// import quantum-circuit npm module
const QuantumCircuit = require("quantum-circuit");

// create instance of QuantumCircuit object
let circ = new QuantumCircuit();

operation ExportedQsharpCode() : Result {
        using(q_reg = Qubit[3]) {
                X(q_reg[0]);
                X(q_reg[1]);
                X(q_reg[2]);
                CCNOT(q_reg[0], q_reg[1], q_reg[2]);
                let r = M(q_reg[2]);
                ResetAll(q_reg);
                return r;
        }
    }
